use std::env;
use std::process::ExitCode;

#[cfg(unix)]
use std::ffi::CString;
#[cfg(unix)]
use std::os::unix::io::RawFd;

const VERSION_STRING: &str = "wrapfile 0.1.0";
const KEY_LEN: usize = 32;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().skip(1).collect();

    match args.first().map(|s| s.as_str()) {
        Some("--version") if args.len() == 1 => {
            println!("{VERSION_STRING}");
            ExitCode::SUCCESS
        }
        Some("keygen") => run_keygen(&args[1..]),
        _ => {
            print_usage();
            ExitCode::from(2)
        }
    }
}

fn print_usage() {
    eprintln!("Usage: wrapfile --version");
    eprintln!("       wrapfile keygen <KEY_FILE>");
}

fn run_keygen(args: &[String]) -> ExitCode {
    let path = match args {
        [] => {
            eprintln!("wrapfile keygen: missing key file path");
            print_usage();
            return ExitCode::from(2);
        }
        [p] if !p.starts_with('-') => p,
        [p] => {
            eprintln!("wrapfile keygen: unknown option '{p}'");
            print_usage();
            return ExitCode::from(2);
        }
        _ => {
            eprintln!("wrapfile keygen: expected exactly one argument (key file path)");
            print_usage();
            return ExitCode::from(2);
        }
    };

    match generate_key_file(path) {
        Ok(()) => {
            println!("Key saved to {path}");
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("wrapfile keygen: {e}");
            ExitCode::from(1)
        }
    }
}

#[cfg(unix)]
fn generate_key_file(path: &str) -> std::io::Result<()> {
    let c_path = CString::new(path).map_err(|_| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "target path contains a NUL byte",
        )
    })?;

    // Draw the key from the OS CSPRNG first. If the random source is
    // unavailable nothing is ever created at the target path.
    let mut key = [0u8; KEY_LEN];
    if let Err(e) = getrandom::fill(&mut key) {
        key.fill(0);
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            format!("cryptographic random source unavailable: {e}"),
        ));
    }

    // O_CREAT | O_EXCL: fail if anything already exists at the path (file,
    // directory, symlink -- including a dangling one, which O_NOFOLLOW also
    // rejects), so an existing object is never touched or followed.
    // mode 0600: owner read/write from the instant the inode is created;
    // the process umask can only remove bits, never add group/other bits.
    let fd = unsafe {
        libc::open(
            c_path.as_ptr(),
            libc::O_WRONLY
                | libc::O_CREAT
                | libc::O_EXCL
                | libc::O_NOFOLLOW
                | libc::O_CLOEXEC,
            0o600,
        )
    };
    if fd < 0 {
        let e = std::io::Error::last_os_error();
        key.fill(0);
        return Err(std::io::Error::new(
            e.kind(),
            format!("cannot create key file '{path}': {e}"),
        ));
    }
    let fd = fd as RawFd;

    let result = write_key_atomically(fd, &key);
    key.fill(0);

    if result.is_err() {
        // The inode was created by us moments ago via O_EXCL, so removing it
        // cannot remove an object that existed before this invocation.
        unsafe {
            libc::unlink(c_path.as_ptr());
            // On Linux close(2) always releases the fd; any error from a
            // second close is harmless and deliberately ignored.
            libc::close(fd);
        }
    }

    result.map_err(|e| std::io::Error::new(e.kind(), format!("key file '{path}': {e}")))
}

#[cfg(unix)]
fn write_key_atomically(fd: RawFd, key: &[u8; KEY_LEN]) -> std::io::Result<()> {
    // Verify owner-only permissions before any secret byte is written: on a
    // filesystem that cannot honor 0600 (group/other bits set) we must fail
    // rather than leave a key readable by others.
    let mut stat: libc::stat = unsafe { std::mem::zeroed() };
    if unsafe { libc::fstat(fd, &mut stat) } != 0 {
        return Err(std::io::Error::last_os_error())
            .map_err(|e| std::io::Error::new(e.kind(), format!("cannot verify permissions: {e}")));
    }
    if stat.st_mode & 0o077 != 0 {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            "cannot restrict key file to owner-only (0600) permissions",
        ));
    }

    write_all(fd, key)?;

    if unsafe { libc::fsync(fd) } != 0 {
        let e = std::io::Error::last_os_error();
        return Err(std::io::Error::new(
            e.kind(),
            format!("could not flush key file to disk: {e}"),
        ));
    }

    // Do not retry on EINTR: on Unix the descriptor is closed regardless.
    if unsafe { libc::close(fd) } != 0 {
        let e = std::io::Error::last_os_error();
        return Err(std::io::Error::new(
            e.kind(),
            format!("could not finish writing key file: {e}"),
        ));
    }

    Ok(())
}

#[cfg(unix)]
fn write_all(fd: RawFd, mut data: &[u8]) -> std::io::Result<()> {
    while !data.is_empty() {
        let n = unsafe {
            libc::write(
                fd,
                data.as_ptr().cast::<libc::c_void>(),
                data.len(),
            )
        };
        if n < 0 {
            let e = std::io::Error::last_os_error();
            if e.raw_os_error() == Some(libc::EINTR) {
                continue;
            }
            return Err(e);
        }
        if n == 0 {
            return Err(std::io::Error::new(
                std::io::ErrorKind::WriteZero,
                "incomplete write to key file",
            ));
        }
        data = &data[n as usize..];
    }
    Ok(())
}

#[cfg(not(unix))]
fn generate_key_file(_path: &str) -> std::io::Result<()> {
    Err(std::io::Error::new(
        std::io::ErrorKind::Unsupported,
        "keygen is only supported on Unix systems",
    ))
}

